INSERT INTO product (id, category_id, name, subtitle, image_url, price, stock, sales, is_on_sale, detail_html, params_text) VALUES (5150, 7, 'Pampi Shoes', 'Pampi Shoes offer a blend of comfort and style for everyday use. With a versatile design, they are suitable for various casual occasions, providing a trendy and relaxed look.', 'https://cdn.dummyjson.com/product-images/womens-shoes/pampi-shoes/1.webp', 29.99, 48, 76, 1, '<p>Pampi Shoes offer a blend of comfort and style for everyday use. With a versatile design, they are suitable for various casual occasions, providing a trendy and relaxed look.</p><p>Brand: Pampi</p><p>Rating: 3.05/5</p>', '品牌: Pampi; 保修: No warranty');
INSERT INTO product (id, category_id, name, subtitle, image_url, price, stock, sales, is_on_sale, detail_html, params_text) VALUES (5151, 7, 'Red Shoes', 'The Red Shoes make a bold statement with their vibrant red color. Whether for a party or a casual outing, these shoes add a pop of color and style to your wardrobe.', 'https://cdn.dummyjson.com/product-images/womens-shoes/red-shoes/1.webp', 34.99, 12, 81, 1, '<p>The Red Shoes make a bold statement with their vibrant red color. Whether for a party or a casual outing, these shoes add a pop of color and style to your wardrobe.</p><p>Brand: Fashion Express</p><p>Rating: 3.25/5</p>', '品牌: Fashion Express; 保修: No warranty');
INSERT INTO product (id, category_id, name, subtitle, image_url, price, stock, sales, is_on_sale, detail_html, params_text) VALUES (5152, 7, 'IWC Ingenieur Automatic Steel', 'The IWC Ingenieur Automatic Steel watch is a durable and sophisticated timepiece. With a stainless steel case and automatic movement, it combines precision and style for watch enthusiasts.', 'https://cdn.dummyjson.com/product-images/womens-watches/iwc-ingenieur-automatic-steel/1.webp', 4999.99, 90, 73, 1, '<p>The IWC Ingenieur Automatic Steel watch is a durable and sophisticated timepiece. With a stainless steel case and automatic movement, it combines precision and style for watch enthusiasts.</p><p>Brand: IWC</p><p>Rating: 2.93/5</p>', '品牌: IWC; 保修: 1 year warranty');
INSERT INTO product (id, category_id, name, subtitle, image_url, price, stock, sales, is_on_sale, detail_html, params_text) VALUES (5153, 7, 'Rolex Cellini Moonphase', 'The Rolex Cellini Moonphase watch is a masterpiece of horology. Featuring a moon phase complication, it showcases the craftsmanship and elegance that Rolex is renowned for.', 'https://cdn.dummyjson.com/product-images/womens-watches/rolex-cellini-moonphase/1.webp', 15999.99, 51, 95, 1, '<p>The Rolex Cellini Moonphase watch is a masterpiece of horology. Featuring a moon phase complication, it showcases the craftsmanship and elegance that Rolex is renowned for.</p><p>Brand: Rolex</p><p>Rating: 3.83/5</p>', '品牌: Rolex; 保修: 1 month warranty');
INSERT INTO product (id, category_id, name, subtitle, image_url, price, stock, sales, is_on_sale, detail_html, params_text) VALUES (5154, 7, 'Rolex Datejust Women', 'The Rolex Datejust Women''s watch is an iconic timepiece designed for women. With a timeless design and a date complication, it offers both elegance and functionality.', 'https://cdn.dummyjson.com/product-images/womens-watches/rolex-datejust-women/1.webp', 10999.99, 9, 71, 1, '<p>The Rolex Datejust Women''s watch is an iconic timepiece designed for women. With a timeless design and a date complication, it offers both elegance and functionality.</p><p>Brand: Rolex</p><p>Rating: 2.86/5</p>', '品牌: Rolex; 保修: 5 year warranty');
INSERT INTO product (id, category_id, name, subtitle, image_url, price, stock, sales, is_on_sale, detail_html, params_text) VALUES (5155, 7, 'Watch Gold for Women', 'The Gold Women''s Watch is a stunning accessory that combines luxury and style. Featuring a gold-plated case and a chic design, it adds a touch of glamour to any outfit.', 'https://cdn.dummyjson.com/product-images/womens-watches/watch-gold-for-women/1.webp', 799.99, 9, 106, 1, '<p>The Gold Women''s Watch is a stunning accessory that combines luxury and style. Featuring a gold-plated case and a chic design, it adds a touch of glamour to any outfit.</p><p>Brand: Fashion Gold</p><p>Rating: 4.24/5</p>', '品牌: Fashion Gold; 保修: 2 year warranty');
INSERT INTO product (id, category_id, name, subtitle, image_url, price, stock, sales, is_on_sale, detail_html, params_text) VALUES (5156, 7, 'Women''s Wrist Watch', 'The Women''s Wrist Watch is a versatile and fashionable timepiece for everyday wear. With a comfortable strap and a simple yet elegant design, it complements various styles.', 'https://cdn.dummyjson.com/product-images/womens-watches/women's-wrist-watch/1.webp', 129.99, 12, 88, 1, '<p>The Women''s Wrist Watch is a versatile and fashionable timepiece for everyday wear. With a comfortable strap and a simple yet elegant design, it complements various styles.</p><p>Brand: Fashion Co.</p><p>Rating: 3.52/5</p>', '品牌: Fashion Co.; 保修: 1 year warranty');
